<?php
namespace App\Http\Controllers;use App\Http\Requests\CsvRequest;use App\Services\CsvService;use Illuminate\Http\JsonResponse;
final readonly class CsvController {public function __construct(private CsvService $csv,private ValidationController $validation){}public function __invoke(CsvRequest $request):JsonResponse{$d=$request->validated();$emails=[];foreach($request->file('files')as$file)$emails=array_merge($emails,$this->csv->emails($this->csv->rows($file),$d['email_column']??null));$emails=array_values(array_unique($emails));if($d['gmail_only']??false)$emails=array_values(array_filter($emails,fn(string $e):bool=>str_ends_with(strtolower($e),'@gmail.com')));$results=array_map(fn(string $e):array=>$this->validation->one($e,$d),$emails);return response()->json(['ok'=>true,'data'=>['results'=>$results,'count'=>count($results)]]);}}
